insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-150', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'On descending a group, the atomic radius of the elements generally', '["decreases","increases","becomes zero","is independent of the new shell"]'::jsonb, 1, 'Each step down adds a principal shell, which outweighs the extra nuclear charge.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'atomic-ionic-radius') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
