insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-151', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'A cation is always smaller than the parent atom from which it is formed because', '["a new shell is added","electrons are lost and the remaining cloud is held more tightly","nuclear charge decreases","the ion gains extra shielding"]'::jsonb, 1, 'Fewer electrons and a higher Zeff/electron ratio contract the ion relative to the atom.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'easy', 'atomic-ionic-radius') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
